from typing import List, Optional, Dict, Any
from pydantic import BaseModel, Field


class EvaluationSample(BaseModel):
    """A ground-truth reference sample for evaluation."""
    id: str
    query: str
    ground_truth_answer: str
    ground_truth_contexts: List[str]
    department: Optional[str] = None
    metadata: Dict[str, Any] = Field(default_factory=dict)


class EvaluationPrediction(BaseModel):
    """Output generated by the RAG system under evaluation."""
    sample_id: str
    generated_answer: str
    retrieved_contexts: List[str]
    citations: List[Dict[str, Any]] = Field(default_factory=list)
    latency_ms: float = 0.0


class MetricScore(BaseModel):
    """Evaluation score for a specific metric."""
    metric_name: str
    score: float = Field(ge=0.0, le=1.0)
    details: Optional[str] = None


class SampleEvaluationResult(BaseModel):
    """Computed evaluation metrics for a single sample."""
    sample_id: str
    query: str
    generated_answer: str
    faithfulness: float = Field(ge=0.0, le=1.0)
    answer_relevance: float = Field(ge=0.0, le=1.0)
    context_precision: float = Field(ge=0.0, le=1.0)
    context_recall: float = Field(ge=0.0, le=1.0)
    citation_accuracy: float = Field(ge=0.0, le=1.0)
    overall_score: float = Field(ge=0.0, le=1.0)
    latency_ms: float = 0.0
    details: Dict[str, Any] = Field(default_factory=dict)


class BenchmarkReport(BaseModel):
    """Aggregated benchmark report across all evaluated samples."""
    timestamp: str
    total_samples: int
    mean_faithfulness: float
    mean_answer_relevance: float
    mean_context_precision: float
    mean_context_recall: float
    mean_citation_accuracy: float
    mean_overall_score: float
    mean_latency_ms: float
    results: List[SampleEvaluationResult]
